package com.shoply.infrastructure.web.controller;
import com.shoply.application.dto.CartDto; import com.shoply.application.service.CartService; import com.shoply.infrastructure.web.request.*; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cart") public class CartController {private final CartService cart;public CartController(CartService cart){this.cart=cart;}@GetMapping public CartDto get(Authentication auth){return cart.get(customerId(auth));}@PostMapping("/items") public CartDto add(Authentication auth,@Valid @RequestBody AddCartItemRequest request){return cart.add(customerId(auth),request.productId(),request.quantity());}@PutMapping("/items/{productId}") public CartDto update(Authentication auth,@PathVariable UUID productId,@Valid @RequestBody UpdateCartItemRequest request){return cart.update(customerId(auth),productId,request.quantity());}@DeleteMapping("/items/{productId}") public CartDto remove(Authentication auth,@PathVariable UUID productId){return cart.remove(customerId(auth),productId);}private UUID customerId(Authentication auth){return UUID.fromString(auth.getName());}}
